30	/** Coerces a persisted hotbar index to a finite integer within 0..HOTBAR_SLOTS-1. */
31	function normalizeSelectedSlot(value: number): number {
32	  const index = Number.isFinite(value) ? Math.floor(value) : 0;
33	  return Math.max(0, Math.min(HOTBAR_SLOTS - 1, index));
34	}
35	
36	export function migrateSaveV1toV2(save: SaveDataV1): SaveDataV2 {
37	  const migrated: SaveDataV2 = { ...save, version: 2, selectedSlot: normalizeSelectedSlot(save.selectedSlot) };
38	
39	  if (Array.isArray(save.inventorySlots)) {
40	    const packed: Array<{ id: string | null; count: number; durability?: number }> = [];
41	    for (const saved of save.inventorySlots) {
42	      if (!saved?.id || saved.count <= 0) continue;
43	      // Items without durability stack; merge them into an earlier stack first.
44	      const stackable = ITEM_DEF_BY_ID[saved.id] ? !ITEM_DEF_BY_ID[saved.id].maxDurability : false;
45	      let remaining = saved.count;
46	      if (stackable) {
47	        for (const slot of packed) {
48	          if (slot.id !== saved.id || slot.count >= MAX_STACK_SIZE) continue;
49	          const moved = Math.min(MAX_STACK_SIZE - slot.count, remaining);
50	          slot.count += moved;
51	          remaining -= moved;
52	          if (remaining === 0) break;
53	        }
54	      }
55	      while (remaining > 0 && packed.length < INVENTORY_SLOTS) {
56	        const moved = Math.min(maxStackSizeForItem(saved.id), remaining);
57	        packed.push({ id: saved.id, count: moved, durability: saved.durability });
58	        remaining -= moved;
59	      }
60	    }
61	    migrated.inventorySlots = packed;
62	  }
63	
64	  return migrated;
65	}
66	
67	/**
68	 * Migrates a v2 save to v3 — a pure version bump. The new persisted fields
69	 * (dayClock, hearts, hunger, spawnPoint) are optional, so an older save simply
70	 * loads with the engine's defaults for them.
71	 */
72	export function migrateSaveV2toV3(save: SaveDataV2): SaveDataV3 {
73	  return { ...save, version: 3 };
74	}
75	
76	/**
77	 * Migrates a v3 save to v4 — a pure version bump. `blockEntities` (chest
78	 * contents) is optional, so a pre-chest save simply loads with no containers.
79	 */
80	export function migrateSaveV3toV4(save: SaveDataV3): SaveDataV4 {
81	  return { ...save, version: 4 };
82	}
83	
84	/**
85	 * Migrates a v4 save to v5 — a pure version bump. `lootedChests` is optional,
86	 * so a pre-dungeon save simply loads with no dungeon chests yet looted. (In
87	 * practice the SAVE_KEY bump to v6 discards pre-dungeon saves, but the
88	 * migration keeps the version chain complete and the readers total.)
89	 */
90	export function migrateSaveV4toV5(save: SaveDataV4): SaveDataV5 {
91	  return { ...save, version: 5 };
92	}
93	
94	/**
95	 * Migrates a v5 save to v6 — a pure version bump. `effects` (active status
96	 * effects) is optional, so a pre-effect save simply loads with none active.
97	 */
98	export function migrateSaveV5toV6(save: SaveDataV5): SaveDataV6 {
99	  return { ...save, version: 6 };
100	}
101	
102	/**
103	 * Migrates a v6 save to v7 — a pure version bump. `xp` (and per-slot
104	 * `enchantments`) are optional, so a pre-XP save simply loads with `xp` 0 and no
105	 * enchantments.
106	 */
107	export function migrateSaveV6toV7(save: SaveDataV6): SaveDataV7 {
108	  return { ...save, version: 7 };
109	}
110	
111	/**
112	 * Migrates a v7 save to v8 — a pure version bump. `gameMode` is optional, so a
113	 * pre-mode save simply loads as "survival" (see restoreGameMode).
114	 */
115	export function migrateSaveV7toV8(save: SaveDataV7): SaveDataV8 {
116	  return { ...save, version: 8 };
117	}
118	
119	/**
120	 * Migrates a v8 save to v9 — a pure version bump. `difficulty` is optional, so a
121	 * pre-difficulty save simply loads as "normal" (see restoreDifficulty).
122	 */
123	export function migrateSaveV8toV9(save: SaveDataV8): SaveData {
124	  return { ...save, version: 9 };
125	}
126	
127	// Storage is injectable so save logic can be tested without a browser.
128	export function readSave(saveKey: string, storage: Storage = localStorage): SaveData | null {
129	  try {
130	    const raw = storage.getItem(saveKey);
131	    if (!raw) return null;
132	    const parsed = JSON.parse(raw) as SaveData | SaveDataV8 | SaveDataV7 | SaveDataV6 | SaveDataV5 | SaveDataV4 | SaveDataV3 | SaveDataV2 | SaveDataV1;
133	    if (!parsed || !Number.isFinite(parsed.seed) || !Array.isArray(parsed.changes)) return null;
134	    let migrated: SaveDataV2 | SaveDataV3 | SaveDataV4 | SaveDataV5 | SaveDataV6 | SaveDataV7 | SaveDataV8 | SaveData =
135	      parsed.version === 1 ? migrateSaveV1toV2(parsed) : parsed;
