1	import * as THREE from "three";
2	import { collidesAt, voxelRaycast } from "@/lib/world";
3	import {
4	  ARROW_TTL,
5	  BOSS_ARROW_DAMAGE,
6	  BOSS_ARROW_SPEED,
7	  BOSS_MELEE_DAMAGE,
8	  BOSS_MELEE_REACH,
9	  BOSS_MINION_CAP,
10	  BOSS_SPREAD,
11	  BOSS_SUMMON_INTERVAL_SECONDS,
12	  CREEPER_ABORT_RANGE,
13	  CREEPER_EXPLOSION_POWER,
14	  CREEPER_FUSE_RANGE,
15	  CREEPER_FUSE_SECONDS,
16	  HOSTILE_BURN_ABOVE_DAYLIGHT,
17	  HOSTILE_CAP,
18	  MOB_ARROW_KNOCKBACK,
19	  SKELETON_ARROW_DAMAGE,
20	  SKELETON_ARROW_SPEED,
21	  SKELETON_FIRE_VGAP,
22	  SKELETON_LEAD_FACTOR,
23	  SKELETON_STANDOFF_MAX,
24	  SKELETON_STANDOFF_MIN,
25	  SPIDER_AGGRO_BELOW_DAYLIGHT
26	} from "@/lib/game/config";
27	import { MOB_TEMPLATES } from "@/lib/game/mobs";
28	import { mobsThreaten } from "@/lib/game/gameModes";
29	import type { EmitGameEvent, GameState, MobState } from "../state";
30	import { spawnArrow } from "../projectiles";
31	import { explode } from "./explosion";
32	import { pushMob } from "./spawnDirector";
33	import type { SurfaceYAtFn } from "@/lib/game/spawn";
34	
35	// Scratch vectors — per-frame tick over every mob must not allocate.
36	const UP = new THREE.Vector3(0, 1, 0);
37	const scratchToPlayer = new THREE.Vector3();
38	const scratchToPlayer3D = new THREE.Vector3();
39	const scratchMobEye = new THREE.Vector3();
40	const scratchPlayerAim = new THREE.Vector3();
41	const scratchRay = new THREE.Vector3();
42	const scratchMobFeet = new THREE.Vector3();
43	const scratchAim = new THREE.Vector3();
44	
45	/**
46	 * A ranged mob looses an arrow from its eye toward the player's chest, leading a
47	 * moving target by a fraction of the arrow's travel time. The arrow is not
48	 * player-owned, so it only ever hits the player (never the firer or other mobs).
49	 */
50	function fireMobArrow(state: GameState, mob: MobState, damage: number, speed: number, emit: EmitGameEvent): void {
51	  const { player } = state;
52	  const eyeY = mob.position.y + mob.halfHeight * 0.7;
53	  const dist = Math.hypot(player.position.x - mob.position.x, player.position.z - mob.position.z);
54	  const lead = (dist / speed) * SKELETON_LEAD_FACTOR;
55	  scratchAim.set(
56	    player.position.x + player.velocity.x * lead - mob.position.x,
57	    player.position.y + 0.9 - eyeY,
58	    player.position.z + player.velocity.z * lead - mob.position.z
59	  );
60	  spawnArrow(state, mob.position.x, eyeY, mob.position.z, scratchAim, {
61	    speed,
62	    damage,
63	    knockback: MOB_ARROW_KNOCKBACK,
64	    fromPlayer: false,
65	    ttl: ARROW_TTL
66	  });
67	  emit({ type: "mobAttacked", kind: mob.kind });
68	}
69	
70	/** The boss looses a 3-arrow horizontal spread aimed at the player's chest. */
71	function fireBossSpread(state: GameState, mob: MobState, emit: EmitGameEvent): void {
72	  const { player } = state;
73	  const eyeY = mob.position.y + mob.halfHeight * 0.7;
74	  const baseX = player.position.x - mob.position.x;
75	  const baseY = player.position.y + 0.9 - eyeY;
76	  const baseZ = player.position.z - mob.position.z;
77	  for (let spread = -1; spread <= 1; spread += 1) {
78	    scratchAim.set(baseX, baseY, baseZ);
79	    if (spread !== 0) scratchAim.applyAxisAngle(UP, spread * BOSS_SPREAD);
80	    spawnArrow(state, mob.position.x, eyeY, mob.position.z, scratchAim, {
81	      speed: BOSS_ARROW_SPEED,
82	      damage: BOSS_ARROW_DAMAGE,
83	      knockback: MOB_ARROW_KNOCKBACK,
84	      fromPlayer: false,
85	      ttl: ARROW_TTL
86	    });
87	  }
88	  emit({ type: "mobAttacked", kind: mob.kind });
89	}
90	
91	/**
92	 * The boss periodically conjures a skeleton or zombie nearby while it is engaged,
93	 * up to its own minion cap and the shared global hostile cap.
94	 */
95	function tickBossSummon(state: GameState, mob: MobState, dt: number, deps: MobTickDeps): void {
96	  mob.summonTimer = (mob.summonTimer ?? 0) - dt;
97	  if (mob.summonTimer > 0) return;
98	  mob.summonTimer = BOSS_SUMMON_INTERVAL_SECONDS;
99	
100	  let minions = 0;
101	  let hostiles = 0;
102	  for (const other of state.mobs) {
103	    if (!other.hostile) continue;
104	    hostiles += 1;
105	    if (other.kind !== "boss") minions += 1;
106	  }
107	  if (minions >= BOSS_MINION_CAP || hostiles >= HOSTILE_CAP) return;
108	
109	  const kind = deps.rng() < 0.5 ? "skeleton" : "zombie";
110	  const angle = deps.rng() * Math.PI * 2;
111	  const radius = 2 + deps.rng() * 2;
112	  const mx = mob.position.x + Math.cos(angle) * radius;
