  const manifest = readWorlds(storage);
  const next: WorldsManifest = {
    version: 1,
    worlds: manifest.worlds.map((w) => (w.id === id ? { ...w, name: sanitizeName(name, w.name, MAX_WORLD_NAME) } : w))
  };
  writeManifest(WORLDS_KEY, next, storage);
  return next;
}

