  const {
    attachMount,
    attachMinimap,
    locked,
    rendererError,
    gameMode,
    difficulty,
    giveCreativeItem,
    setGameMode,
    setDifficulty,
    selectedSlot,
    setSelectedSlot,
    capsActive,
    inventoryOpen,
    inventory,
    equippedArmor,
    armorPoints,
    hearts,
    hunger,
    oxygen,
